static void __cfg80211_sme_scan_done ( struct net_device * dev ) { struct wireless_dev * wdev = dev -> ieee80211_ptr ; struct cfg80211_registered_device * rdev = wiphy_to_rdev ( wdev -> wiphy ) ; struct cfg80211_bss * bss ; ASSERT_WDEV_LOCK ( wdev ) ; if ( wdev -> conn -> state != CFG80211_CONN_SCANNING && wdev -> conn -> state != CFG80211_CONN_SCAN_AGAIN ) { return ; } bss = cfg80211_get_conn_bss ( wdev ) ; if ( bss ) { cfg80211_put_bss ( & rdev -> wiphy , bss ) ; } else { schedule_work ( & rdev -> conn_work ) ; } } 